def xml(p,selector=None):
 p=pathlib.Path(p); e=ET.parse(p).getroot();cs=[]
 for c in e.findall('testcase'):
  if selector and selector.lower() not in c.attrib['name'].lower():continue
  cs.append({'name':c.attrib['name'],'class':c.attrib.get('classname'),'passed':all(c.find(n) is None for n in ['failure','error','skipped'])})
 assert cs,(p,selector)
 record(p,'actual selected XML reconciled to bounded case')
 return {'path':str(p),'sha256':sha(p),'suite':{k:e.attrib.get(k) for k in ['name','tests','failures','errors','skipped','timestamp']},'selected_cases':cs,'selected_all_pass':all(c['passed'] for c in cs)}
